{"witnessCode": "import { describe, it } from 'node:test';
import assert from 'node:assert/strict';
import normalizeUrl from '../index.js';

describe('normalizeUrl dot-in-protocol', () => {
  it('should prepend default protocol for protocols containing a dot', () => {
    const input = 'foo.bar:path';
    const expected = 'http:foo.bar:path';
    assert.strictEqual(normalizeUrl(input), expected);
  });
});"}
